// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.guardrailsimport com.roshan.persona.brain.context.DeviceContextimport com.roshan.persona.brain.context.ThermalStatusimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Local LLM guardrails (Fixes #24 — thermal + RAM + battery checks). * * Before invoking the local LLM, the guardrails check device state: *   - Thermal: if device too hot, defer to cloud (avoid throttling + crashes) *   - RAM: if insufficient RAM for model + KV cache, defer to cloud *   - Battery: if battery critical and not charging, defer to cloud * * Returns [GuardrailDecision.Proceed] if all checks pass, or * [GuardrailDecision.Defer] with reason + target layer if any check fails. * * @see <a href="docs/spec/module2-spec-review.pdf">§7.3 Thermal + RAM Guardrails</a> */@Singletonclass LocalLlmGuardrails @Inject constructor() {    /**     * Check whether the local LLM should run on this device right now.     *     * @param device current device state     * @param provider the LLM provider (for model size + VRAM info)     * @return decision to proceed or defer     */    fun shouldRunLlm(        device: DeviceContext,        provider: LocalLlmProvider,    ): GuardrailDecision {        // ─── Thermal check ────────────────────────────────────────────────        // SEVERE+ → always defer (device will throttle aggressively)        if (device.thermalStatus.isAtLeast(ThermalStatus.SEVERE)) {            return GuardrailDecision.Defer(                reason = "Device too hot (thermal=${device.thermalStatus})",                deferTo = Layer.CLOUD,            )        }        // MODERATE + low battery → defer (combo is risky)        if (device.thermalStatus == ThermalStatus.MODERATE && device.batteryLevel < 30) {            return GuardrailDecision.Defer(                reason = "Thermal moderate + low battery (${device.batteryLevel}%)",                deferTo = Layer.CLOUD,            )        }        // ─── RAM check ────────────────────────────────────────────────────        // Model needs ~2x its size for KV cache + inference buffers        val requiredRamMb = (provider.modelSizeBytes / (1024 * 1024) * 2).toInt()        if (device.availableRamMb < requiredRamMb) {            return GuardrailDecision.Defer(                reason = "Insufficient RAM (${device.availableRamMb}MB < ${requiredRamMb}MB needed)",                deferTo = Layer.CLOUD,            )        }        // ─── GPU VRAM check (if model needs GPU) ──────────────────────────        if (provider.availableVramMb > 0 && device.gpuAvailable) {            val modelVramMb = (provider.modelSizeBytes / (1024 * 1024)).toInt()            if (device.gpuVramMb < modelVramMb) {                return GuardrailDecision.Defer(                    reason = "Insufficient GPU VRAM (${device.gpuVramMb}MB < ${modelVramMb}MB needed)",                    deferTo = Layer.CLOUD,                )            }        }        // ─── Battery check ────────────────────────────────────────────────        // Don't drain battery on LLM if < 15% and not charging        if (device.batteryLevel < 15 && !device.isCharging) {            return GuardrailDecision.Defer(                reason = "Battery critical (${device.batteryLevel}%) and not charging",                deferTo = Layer.CLOUD,            )        }        // ─── All checks passed ────────────────────────────────────────────        return GuardrailDecision.Proceed    }    /**     * Check whether the local LLM should be loaded at all (offline check).     * Used at app startup to decide if LLM should be warmed up.     */    fun shouldLoadModel(device: DeviceContext): GuardrailDecision {        // Don't load if device is severely hot        if (device.thermalStatus.isAtLeast(ThermalStatus.SEVERE)) {            return GuardrailDecision.Defer(                reason = "Device too hot to load model",                deferTo = Layer.CLOUD,            )        }        // Don't load if battery < 10% and not charging        if (device.batteryLevel < 10 && !device.isCharging) {            return GuardrailDecision.Defer(                reason = "Battery too low to load model",                deferTo = Layer.CLOUD,            )        }        return GuardrailDecision.Proceed    }}/** * Guardrail decision. */sealed interface GuardrailDecision {    /** All checks passed — proceed with local LLM. */    data object Proceed : GuardrailDecision    /** Defer to another layer (typically cloud). */    data class Defer(        val reason: String,        val deferTo: Layer,    ) : GuardrailDecision}/** * Target layer for deferral. */enum class Layer(val number: Int) {    CLOUD(4),    AGENTIC(5),    ;}